internal final class GUPPeriodicDiscountCopy
{
    RetailPeriodicDiscount periodicDiscountOrig;

    #OCCRetryCount

}

Method.Source:
private void run()
{
    try
    {
        ttsbegin;

        periodicDiscountOrig.copyRetailPeriodicDiscount();

        ttscommit;
    }
    catch (Exception::Deadlock)
    {
        retry;
    }
    catch (Exception::Error)
    {
        ttsabort;
        Box::stop("@GLS110288");
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw Exception::UpdateConflict;
        }
    }
}

private RetailPeriodicDiscount parmGUPPeriodicDiscountOrig (RetailPeriodicDiscount _periodicDiscountOrig = periodicDiscountOrig)
{
    periodicDiscountOrig = _periodicDiscountOrig;

    return periodicDiscountOrig;
}

public static void main(Args _args)
{
    GUPPeriodicDiscountCopy periodicDiscountCopy = new GUPPeriodicDiscountCopy();

    if (_args && _args.record() && _args.record() is RetailPeriodicDiscount)
    {
        periodicDiscountCopy.parmGUPPeriodicDiscountOrig(_args.record());
        periodicDiscountCopy.run();

        FormRun formRun = _args.caller();

        if(formRun)
        {
            if (formRun.dataSource(tableStr(RetailPeriodicDiscount)))
            {
                FormDataSource formDS = formRun.dataSource(tableStr(RetailPeriodicDiscount));
                formDS.research(true);
            }
        }
    }
    else
    {
        throw error(strFmt("@SYS27147", new DictClass(classIdGet(periodicDiscountCopy)).name()));
    }
}
